<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/document_manager.php';require_once __DIR__.'/includes/pdf_documents.php';require_permission('contracts.view');
$id=(int)($_GET['id']??$_POST['id']??0);$stmt=db()->prepare('SELECT ct.*,c.company_name,c.tax_id,c.country,c.city,c.address,c.email client_email,c.contact_name client_contact,u.name owner_name FROM contracts ct JOIN clients c ON c.id=ct.client_id LEFT JOIN users u ON u.id=ct.owner_user_id WHERE ct.id=?');$stmt->execute([$id]);$contract=$stmt->fetch();if(!$contract){http_response_code(404);exit('Contrato no encontrado.');}
if($_SERVER['REQUEST_METHOD']==='POST'&&has_permission('contracts.status')){verify_csrf();$status=(string)($_POST['status']??'');if(in_array($status,['draft','sent','approved','rejected','signed','cancelled'],true)){db()->prepare('UPDATE contracts SET status=?,signed_at=IF(?=\'signed\',NOW(),signed_at) WHERE id=?')->execute([$status,$status,$id]);flash('success','Estado actualizado.');redirect('contract_view.php?id='.$id);}}
$pageTitle=$contract['contract_number'];$approvalUrl=app_url('contract_public.php?token='.$contract['public_token']);require __DIR__.'/includes/header.php';?>
<section class="panel"><div class="panel-header"><div><h2><?=e($contract['title'])?></h2><span class="table-sub"><?=e($contract['company_name'])?> · <?=e(format_date($contract['issue_date']))?> · <?=e($contract['owner_name']?:'Sin asignar')?></span></div><div class="actions"><?php if(has_permission('contracts.edit')&&in_array($contract['status'],['draft','rejected'],true)):?><a class="btn btn-light" href="contract_form.php?id=<?=$id?>">EDITAR</a><?php endif;?><?php if(has_permission('contracts.send')):?><a class="btn btn-secondary" href="contract_send.php?id=<?=$id?>">ENVIAR AL CLIENTE</a><?php endif;?><?php if(in_array($contract['status'],['approved','signed'],true)):?><a class="btn btn-primary" href="contract_pdf.php?id=<?=$id?>">DESCARGAR PDF PARA FIRMA</a><?php endif;?></div></div><div class="panel-body"><div class="contract-meta-grid"><div class="detail"><small>Número</small><strong><?=e($contract['contract_number'])?></strong></div><div class="detail"><small>Estado</small><strong><span class="badge badge-<?=e(contract_status_class($contract['status']))?>"><?=e(contract_status_label($contract['status']))?></span></strong></div><div class="detail"><small>Idioma</small><strong><?=e(language_label($contract['language']))?></strong></div><div class="detail"><small>Destinatario</small><strong><?=e($contract['recipient_name']?:$contract['client_contact']?:'—')?></strong></div><div class="detail"><small>Email</small><strong><?=e($contract['recipient_email']?:$contract['client_email']?:'—')?></strong></div><div class="detail"><small>Aprobado por</small><strong><?=e($contract['approver_name']?:'—')?></strong></div></div></div></section>
<section class="panel"><div class="panel-header"><div><h2>Contenido del contrato</h2><span class="table-sub">Esta es la versión exacta enviada al cliente.</span></div></div><div class="panel-body"><article class="contract-document"><h1><?=e($contract['title'])?></h1><div class="contract-copy"><?=nl2br(e($contract['content']))?></div><?php if($contract['approver_comment']):?><div class="alert alert-info"><strong>Comentario del cliente:</strong><br><?=nl2br(e($contract['approver_comment']))?></div><?php endif;?></article></div></section>
<section class="panel"><div class="panel-header"><h2>Aprobación y estado</h2></div><div class="panel-body form-grid"><label class="full">Enlace de aprobación<input readonly value="<?=e($approvalUrl)?>"></label><?php if(has_permission('contracts.status')):?><form method="post" class="full form-grid"><?=csrf_field()?><label>Actualizar estado<select name="status"><?php foreach(['draft','sent','approved','rejected','signed','cancelled']as$s):?><option value="<?=$s?>" <?=$contract['status']===$s?'selected':''?>><?=e(contract_status_label($s))?></option><?php endforeach;?></select></label><div class="form-actions" style="align-self:end"><button class="btn btn-secondary">GUARDAR ESTADO</button></div></form><?php endif;?></div></section><?php if(has_permission('documents.view'))echo dms_related_panel('contract',$id);?><?php require __DIR__.'/includes/footer.php';?>
